// coding-misk · Prima luce
// song composed with sections and tracks: each track plays its clips, switched on by the section lane (1 plays, 0 is silent, values in between fade)
// each .analyze("…") lights up its instrument in the Stage visual
setcpm(140/4)

const SECTIONS = [['Crescendo', 62], ['Crescendo 2', 58], ['Loop', 32], ['Salita', 32], ['Respiro', 8], ['Luce', 24], ['Strip', 8]]
const TEMPO = {'Crescendo': 140, 'Crescendo 2': 140, 'Loop': 140, 'Salita': 140, 'Respiro': 140, 'Luce': 140, 'Strip': 140}

// section lanes: 1 plays, 0 is silent, values in between fade
const section1 = "<1!62 0!162>"  // Crescendo · 62 bars · 140 BPM · G · Gm
const section2 = "<0!62 1!58 0!104>"  // Crescendo 2 · 58 bars · 140 BPM · G · Gm Gm F F
const section3 = "<0!120 1!32 0!72>"  // Loop · 32 bars · 140 BPM · G · Gm
const section4 = "<0!152 1!32 0!40>"  // Salita · 32 bars · 140 BPM · G · Gm Gm F F
const section5 = "<0!184 1!8 0!32>"  // Respiro · 8 bars · 140 BPM · G · Gm Gm F F
const section6 = "<0!192 1!24 0!8>"  // Luce · 24 bars · 140 BPM · G · Gm Gm F F
const section7 = "<0!216 1!8>"  // Strip · 8 bars · 140 BPM · G · Gm Gm F F

// ========== drums ==========
// Crescendo · bars 1-62 · pattern floor~2
// Drums · RolandTR909
$: s("[bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~]").bank("RolandTR909").gain(0.68).lpf(2000).mask(section1).velocity(section1).orbit(1).analyze("kick")
// Crescendo 2 · bars 63-120 · pattern floor~2
$: s("[bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~]").bank("RolandTR909").gain(0.68).lpf(2000).mask(section2).velocity(section2).orbit(1).analyze("kick")
// Loop · bars 121-152 · pattern floor~2
$: s("[bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~]").bank("RolandTR909").gain(0.68).lpf(2000).mask(section3).velocity(section3).orbit(1).analyze("kick")
// Salita · bars 153-184 · pattern floor~2
$: s("[bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~]").bank("RolandTR909").gain(0.68).lpf(2000).mask(section4).velocity(section4).orbit(1).analyze("kick")
$: s("sd*16").bank("RolandTR909").gain(saw.range(.15, .75)).mask("<0!23 1 0!8>").mask(section4).velocity(section4).orbit(1).analyze("snare")
// Luce · bars 193-216 · pattern floor~2
$: s("[bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~]").bank("RolandTR909").gain(0.68).lpf(2000).mask(section6).velocity(section6).orbit(1).analyze("kick")
$: s("cr").bank("RolandTR909").gain(.55).room(.4).mask("<1 0!23>").mask(section6).velocity(section6).orbit(1).analyze("fx")
// Strip · bars 217-224 · pattern floor~2
$: s("[bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~]").bank("RolandTR909").gain(0.68).lpf(2000).mask(section7).velocity(section7).orbit(1).analyze("kick")

